//! Port of `packages/mermaid/src/diagrams/flowchart/parser/flow-edges.spec.js`. Test names follow
//! the spec's titles in snake_case. Where two titles are the same, the later test gets a `_2` (or
//! `_3`) suffix. The `it.each` and `for` cases are generated by the macros below from the spec's
//! data, with the same inputs and the same expectations.

use ferrigura_model::flowchart::{FlowEdge, FlowVertex, FlowchartDiagram};
use ferrigura_syntax::flowchart::parse;

/// The vertex with the given id. Panics with the id when there is none, as the spec's
/// `vert.get(id)` would give `undefined`.
fn vertex<'a>(diagram: &'a FlowchartDiagram, id: &str) -> &'a FlowVertex {
    diagram
        .vertices
        .iter()
        .find(|vertex| vertex.id == id)
        .unwrap_or_else(|| panic!("no vertex {id}"))
}

/// The checks every single-edge test makes: vertices A and B exist, and there is one edge from A
/// to B. Returns that edge.
fn single_edge_a_to_b(diagram: &FlowchartDiagram) -> &FlowEdge {
    assert_eq!(vertex(diagram, "A").id, "A");
    assert_eq!(vertex(diagram, "B").id, "B");
    assert_eq!(diagram.edges.len(), 1);
    let edge = &diagram.edges[0];
    assert_eq!(edge.start, "A");
    assert_eq!(edge.end, "B");
    edge
}

/// A test of one edge from A to B that checks its type, text and stroke.
macro_rules! edge_test {
    ($name:ident, $input:expr, $edge_type:expr, $stroke:expr, $text:expr) => {
        #[test]
        fn $name() {
            let diagram = parse($input).expect("parses");
            let edge = single_edge_a_to_b(&diagram);
            assert_eq!(edge.edge_type, $edge_type);
            assert_eq!(edge.text, $text);
            assert_eq!(edge.stroke, $stroke);
        }
    };
}

/// A test of one edge from A to B that checks its type, text, stroke and length.
macro_rules! edge_length_test {
    ($name:ident, $input:expr, $edge_type:expr, $stroke:expr, $text:expr, $length:expr) => {
        #[test]
        fn $name() {
            let diagram = parse($input).expect("parses");
            let edge = single_edge_a_to_b(&diagram);
            assert_eq!(edge.edge_type, $edge_type);
            assert_eq!(edge.text, $text);
            assert_eq!(edge.stroke, $stroke);
            assert_eq!(edge.length, Some($length));
        }
    };
}

/// A test of one edge from A to B with the user's id `e1`.
macro_rules! edge_with_id_test {
    ($name:ident, $input:expr, $edge_type:expr, $stroke:expr, $text:expr) => {
        #[test]
        fn $name() {
            let diagram = parse($input).expect("parses");
            let edge = single_edge_a_to_b(&diagram);
            assert_eq!(edge.id, "e1");
            assert_eq!(edge.edge_type, $edge_type);
            assert_eq!(edge.text, $text);
            assert_eq!(edge.stroke, $stroke);
        }
    };
}

