    #[test]
    fn should_handle_multiple_edges() {
        let diagram =
            parse("graph TD;A---|This is the 123 s text|B;\nA---|This is the second edge|B;")
                .expect("parses");
        assert_eq!(vertex(&diagram, "A").id, "A");
        assert_eq!(vertex(&diagram, "B").id, "B");
        assert_eq!(diagram.edges.len(), 2);
        let first = &diagram.edges[0];
        assert_eq!(first.start, "A");
        assert_eq!(first.end, "B");
        assert_eq!(first.edge_type, "arrow_open");
        assert_eq!(first.text, "This is the 123 s text");
        assert_eq!(first.stroke, "normal");
        assert_eq!(first.length, Some(1));
        let second = &diagram.edges[1];
        assert_eq!(second.start, "A");
        assert_eq!(second.end, "B");
        assert_eq!(second.edge_type, "arrow_open");
        assert_eq!(second.text, "This is the second edge");
        assert_eq!(second.stroke, "normal");
        assert_eq!(second.length, Some(1));
    }

